inputs = ['jbw', 'azb', 'ebwzk', 'wz', 'hyzvxw']
outputs = ['jbw', 'akczb', 'ebwigc', 'wkcz', 'hykczvxw']

# Focus on the changed pairs
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:", changed_pairs)

# Analyze each changed pair
for idx, inp, outp in changed_pairs:
    print(f"\nAnalyzing pair {idx}: '{inp}' -> '{outp}'")

    # Find minimal edit
    if len(inp) == len(outp):
        # Same length - substitution
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
    else:
        # Different lengths - insertion/deletion
        print(f"  Length change: {len(inp)} -> {len(outp)}")

